COPY core.cooking_rule (rule_id, cooking_method, aliases, oil_g_min, oil_g_max, oil_g_default, oil_level, salt_equiv_g_min, salt_equiv_g_max, salt_equiv_g_default, salt_level, added_sugar_g_min, added_sugar_g_max, added_sugar_g_default, added_sugar_level, method_applicability, core_assumptions, adjustment_rules, source_meta, import_batch_id) FROM stdin;
CR001	生食/不加热（无调味）	{生食,原味,不加调味}	0	0	0	低	0	0	0	低	0	0	0	低	洗净后直接食用，且没有沙拉酱、酱油、盐、糖、蜂蜜或油性蘸料。	所有调味另计；若配蘸料，按凉拌或实际配方计算。	出现任何油盐糖调味时，不再使用本行；改用实际调味量或最相近复合做法。 在成品150–600g且配方浓度相近时，可按实际成品可食重量/300线性缩放；超出该范围应改用实际配方。	{"meta": {"limitations": "仅估算烹调额外带入成品的油、食盐当量和添加糖，不含原料天然脂肪、天然糖及天然钠；不代表人体实际吸收量。厨师手法、食材吸油性、裹粉、锅具、火候、沥油、汤汁摄入和调味品牌可使结果明显偏离。儿童、孕妇、老年人及慢病人群需另行设定个体化目标。", "source_urls": ["https://en.chinacdc.cn/health_topics/nutrition_health/202206/t20220616_259702.html", "https://www.nhc.gov.cn/guihuaxxs/c100133/201907/2a6ed52f1c264203b5351bdbbadd2da8.shtml", "https://www.nhc.gov.cn/wjw/c100175/202012/681df34f0e8f485fb33e8a659e30f6da.shtml", "https://www.nhc.gov.cn/sps/c100087/202404/90c64c79708740a1bca0ee31e524caf7.shtml"], "rule_version": "1.0.0 (2026-10-17)", "project_basis": "项目估计：以权威每日总量边界、烹饪方式的相对用油/调味强度、家庭与餐饮常见操作及任务给定初始区间为依据，形成可计算的保守区间；未经统一实验测定。", "grade_thresholds": "按默认值分级。油：低≤5g，中>5–15g，偏高>15–25g，高>25g；盐当量：低≤1g，中>1–2g，偏高>2–3g，高>3g；添加糖：低≤2g，中>2–5g，偏高>5–10g，高>10g。阈值均为项目内部规则。", "servings_estimate": 2, "standard_portion_g": 300, "authority_reference": "《中国居民膳食指南（2022）》：成人每日食盐不超过5g、烹调油25–30g、添加糖不超过50g且最好低于25g；《健康中国行动（2019—2030年）》倡导添加糖不高于25g；《餐饮食品营养标识指南》规定1mg钠相当于2.5mg食盐；《营养健康食堂建设指南》建议少用炸、煎、熏、烤并尽量减少油盐糖。上述均为每日总量或原则，不是单道菜测定值。", "calculation_priority": "已知配方/称量值优先；其次用营养标签或餐厅标示；均缺失时才使用本规则。含钠调味品按标签钠量折算：食盐当量(g)=钠(mg)×2.5/1000。", "project_estimate_flag": true, "standard_portion_definition": "成品可食部分300g/份；含随菜食用的汤汁或芡汁，不含骨、壳及弃去的炸油"}, "title": "烹饪方式油盐糖估算规则", "language": "zh-CN", "dataset_id": "cooking-rules-zh-cn-v1", "rule_count": 16, "updated_on": "2026-10-18", "intended_use": "供膳食搭配智能体在缺少完整配方/称量值时，按菜品主要烹饪方式估算额外带入成品的烹调油、食盐当量与添加糖。", "portion_basis": "各区间按一份300g成品可食部分计，约2名成人分食；按实际食用重量线性折算到个人。", "schema_version": "1.0.0"}	1
CR002	清蒸	{蒸,隔水蒸,蒸箱,微波蒸}	0	3	1.5	低	0	1.2	0.6	低	0	1	0.5	低	原料直接蒸熟，可带少量葱姜油、蒸鱼豉油或淡味调味汁。	不勾厚芡、不大量淋热油；随菜食用的汁计入。	无调味取下限；出锅淋油或豉油取上限；若重油浇汁，按实际配方或快炒/红烧规则。 在成品150–600g且配方浓度相近时，可按实际成品可食重量/300线性缩放；超出该范围应改用实际配方。	{"meta": {"limitations": "仅估算烹调额外带入成品的油、食盐当量和添加糖，不含原料天然脂肪、天然糖及天然钠；不代表人体实际吸收量。厨师手法、食材吸油性、裹粉、锅具、火候、沥油、汤汁摄入和调味品牌可使结果明显偏离。儿童、孕妇、老年人及慢病人群需另行设定个体化目标。", "source_urls": ["https://en.chinacdc.cn/health_topics/nutrition_health/202206/t20220616_259702.html", "https://www.nhc.gov.cn/guihuaxxs/c100133/201907/2a6ed52f1c264203b5351bdbbadd2da8.shtml", "https://www.nhc.gov.cn/wjw/c100175/202012/681df34f0e8f485fb33e8a659e30f6da.shtml", "https://www.nhc.gov.cn/sps/c100087/202404/90c64c79708740a1bca0ee31e524caf7.shtml"], "rule_version": "1.0.0 (2026-10-17)", "project_basis": "项目估计：以权威每日总量边界、烹饪方式的相对用油/调味强度、家庭与餐饮常见操作及任务给定初始区间为依据，形成可计算的保守区间；未经统一实验测定。", "grade_thresholds": "按默认值分级。油：低≤5g，中>5–15g，偏高>15–25g，高>25g；盐当量：低≤1g，中>1–2g，偏高>2–3g，高>3g；添加糖：低≤2g，中>2–5g，偏高>5–10g，高>10g。阈值均为项目内部规则。", "servings_estimate": 2, "standard_portion_g": 300, "authority_reference": "《中国居民膳食指南（2022）》：成人每日食盐不超过5g、烹调油25–30g、添加糖不超过50g且最好低于25g；《健康中国行动（2019—2030年）》倡导添加糖不高于25g；《餐饮食品营养标识指南》规定1mg钠相当于2.5mg食盐；《营养健康食堂建设指南》建议少用炸、煎、熏、烤并尽量减少油盐糖。上述均为每日总量或原则，不是单道菜测定值。", "calculation_priority": "已知配方/称量值优先；其次用营养标签或餐厅标示；均缺失时才使用本规则。含钠调味品按标签钠量折算：食盐当量(g)=钠(mg)×2.5/1000。", "project_estimate_flag": true, "standard_portion_definition": "成品可食部分300g/份；含随菜食用的汤汁或芡汁，不含骨、壳及弃去的炸油"}, "title": "烹饪方式油盐糖估算规则", "language": "zh-CN", "dataset_id": "cooking-rules-zh-cn-v1", "rule_count": 16, "updated_on": "2026-10-18", "intended_use": "供膳食搭配智能体在缺少完整配方/称量值时，按菜品主要烹饪方式估算额外带入成品的烹调油、食盐当量与添加糖。", "portion_basis": "各区间按一份300g成品可食部分计，约2名成人分食；按实际食用重量线性折算到个人。", "schema_version": "1.0.0"}	1
CR003	白灼/焯	{白灼,焯水,汆烫}	0	3	1.5	低	0	1.2	0.6	低	0	1	0.5	低	短时沸水加热后沥水食用，可配少量调味汁。	焯水弃去；蘸料或浇汁按实际食用部分计入。	完全原味取下限；蒜蓉油、酱油汁取上限；大量蘸料单独计入。 在成品150–600g且配方浓度相近时，可按实际成品可食重量/300线性缩放；超出该范围应改用实际配方。	{"meta": {"limitations": "仅估算烹调额外带入成品的油、食盐当量和添加糖，不含原料天然脂肪、天然糖及天然钠；不代表人体实际吸收量。厨师手法、食材吸油性、裹粉、锅具、火候、沥油、汤汁摄入和调味品牌可使结果明显偏离。儿童、孕妇、老年人及慢病人群需另行设定个体化目标。", "source_urls": ["https://en.chinacdc.cn/health_topics/nutrition_health/202206/t20220616_259702.html", "https://www.nhc.gov.cn/guihuaxxs/c100133/201907/2a6ed52f1c264203b5351bdbbadd2da8.shtml", "https://www.nhc.gov.cn/wjw/c100175/202012/681df34f0e8f485fb33e8a659e30f6da.shtml", "https://www.nhc.gov.cn/sps/c100087/202404/90c64c79708740a1bca0ee31e524caf7.shtml"], "rule_version": "1.0.0 (2026-10-17)", "project_basis": "项目估计：以权威每日总量边界、烹饪方式的相对用油/调味强度、家庭与餐饮常见操作及任务给定初始区间为依据，形成可计算的保守区间；未经统一实验测定。", "grade_thresholds": "按默认值分级。油：低≤5g，中>5–15g，偏高>15–25g，高>25g；盐当量：低≤1g，中>1–2g，偏高>2–3g，高>3g；添加糖：低≤2g，中>2–5g，偏高>5–10g，高>10g。阈值均为项目内部规则。", "servings_estimate": 2, "standard_portion_g": 300, "authority_reference": "《中国居民膳食指南（2022）》：成人每日食盐不超过5g、烹调油25–30g、添加糖不超过50g且最好低于25g；《健康中国行动（2019—2030年）》倡导添加糖不高于25g；《餐饮食品营养标识指南》规定1mg钠相当于2.5mg食盐；《营养健康食堂建设指南》建议少用炸、煎、熏、烤并尽量减少油盐糖。上述均为每日总量或原则，不是单道菜测定值。", "calculation_priority": "已知配方/称量值优先；其次用营养标签或餐厅标示；均缺失时才使用本规则。含钠调味品按标签钠量折算：食盐当量(g)=钠(mg)×2.5/1000。", "project_estimate_flag": true, "standard_portion_definition": "成品可食部分300g/份；含随菜食用的汤汁或芡汁，不含骨、壳及弃去的炸油"}, "title": "烹饪方式油盐糖估算规则", "language": "zh-CN", "dataset_id": "cooking-rules-zh-cn-v1", "rule_count": 16, "updated_on": "2026-10-18", "intended_use": "供膳食搭配智能体在缺少完整配方/称量值时，按菜品主要烹饪方式估算额外带入成品的烹调油、食盐当量与添加糖。", "portion_basis": "各区间按一份300g成品可食部分计，约2名成人分食；按实际食用重量线性折算到个人。", "schema_version": "1.0.0"}	1
CR004	水煮（捞出食用）	{水煮,汆,涮,煮后沥水}	0	3	1.5	低	0	1.5	0.8	低	0	1	0.5	低	食材在水或清汤中煮熟后捞出，煮液不作为主要食用部分。	不适用于川味水煮油泼菜；蘸料另计。	清水煮取下限；咸汤煮或食用少量汤汁取上限；红油汤底改用干锅/高油复合规则。 在成品150–600g且配方浓度相近时，可按实际成品可食重量/300线性缩放；超出该范围应改用实际配方。	{"meta": {"limitations": "仅估算烹调额外带入成品的油、食盐当量和添加糖，不含原料天然脂肪、天然糖及天然钠；不代表人体实际吸收量。厨师手法、食材吸油性、裹粉、锅具、火候、沥油、汤汁摄入和调味品牌可使结果明显偏离。儿童、孕妇、老年人及慢病人群需另行设定个体化目标。", "source_urls": ["https://en.chinacdc.cn/health_topics/nutrition_health/202206/t20220616_259702.html", "https://www.nhc.gov.cn/guihuaxxs/c100133/201907/2a6ed52f1c264203b5351bdbbadd2da8.shtml", "https://www.nhc.gov.cn/wjw/c100175/202012/681df34f0e8f485fb33e8a659e30f6da.shtml", "https://www.nhc.gov.cn/sps/c100087/202404/90c64c79708740a1bca0ee31e524caf7.shtml"], "rule_version": "1.0.0 (2026-10-17)", "project_basis": "项目估计：以权威每日总量边界、烹饪方式的相对用油/调味强度、家庭与餐饮常见操作及任务给定初始区间为依据，形成可计算的保守区间；未经统一实验测定。", "grade_thresholds": "按默认值分级。油：低≤5g，中>5–15g，偏高>15–25g，高>25g；盐当量：低≤1g，中>1–2g，偏高>2–3g，高>3g；添加糖：低≤2g，中>2–5g，偏高>5–10g，高>10g。阈值均为项目内部规则。", "servings_estimate": 2, "standard_portion_g": 300, "authority_reference": "《中国居民膳食指南（2022）》：成人每日食盐不超过5g、烹调油25–30g、添加糖不超过50g且最好低于25g；《健康中国行动（2019—2030年）》倡导添加糖不高于25g；《餐饮食品营养标识指南》规定1mg钠相当于2.5mg食盐；《营养健康食堂建设指南》建议少用炸、煎、熏、烤并尽量减少油盐糖。上述均为每日总量或原则，不是单道菜测定值。", "calculation_priority": "已知配方/称量值优先；其次用营养标签或餐厅标示；均缺失时才使用本规则。含钠调味品按标签钠量折算：食盐当量(g)=钠(mg)×2.5/1000。", "project_estimate_flag": true, "standard_portion_definition": "成品可食部分300g/份；含随菜食用的汤汁或芡汁，不含骨、壳及弃去的炸油"}, "title": "烹饪方式油盐糖估算规则", "language": "zh-CN", "dataset_id": "cooking-rules-zh-cn-v1", "rule_count": 16, "updated_on": "2026-10-18", "intended_use": "供膳食搭配智能体在缺少完整配方/称量值时，按菜品主要烹饪方式估算额外带入成品的烹调油、食盐当量与添加糖。", "portion_basis": "各区间按一份300g成品可食部分计，约2名成人分食；按实际食用重量线性折算到个人。", "schema_version": "1.0.0"}	1
CR005	汤煮/炖汤（连汤食用）	{汤菜,炖汤,煲汤,砂锅汤}	0	5	2.5	低	1	2.5	1.8	中	0	2	1	低	成品300g包含实际喝下的汤；清汤、羹汤和家庭炖汤。	肉类析出脂肪属于原料脂肪，不记入新增烹调油；本行只记额外加油。	只吃固形物时按实际食用汤汁比例下调盐和糖；浓汤、火锅底料或油汤应单列底料并取更高值。 在成品150–600g且配方浓度相近时，可按实际成品可食重量/300线性缩放；超出该范围应改用实际配方。	{"meta": {"limitations": "仅估算烹调额外带入成品的油、食盐当量和添加糖，不含原料天然脂肪、天然糖及天然钠；不代表人体实际吸收量。厨师手法、食材吸油性、裹粉、锅具、火候、沥油、汤汁摄入和调味品牌可使结果明显偏离。儿童、孕妇、老年人及慢病人群需另行设定个体化目标。", "source_urls": ["https://en.chinacdc.cn/health_topics/nutrition_health/202206/t20220616_259702.html", "https://www.nhc.gov.cn/guihuaxxs/c100133/201907/2a6ed52f1c264203b5351bdbbadd2da8.shtml", "https://www.nhc.gov.cn/wjw/c100175/202012/681df34f0e8f485fb33e8a659e30f6da.shtml", "https://www.nhc.gov.cn/sps/c100087/202404/90c64c79708740a1bca0ee31e524caf7.shtml"], "rule_version": "1.0.0 (2026-10-17)", "project_basis": "项目估计：以权威每日总量边界、烹饪方式的相对用油/调味强度、家庭与餐饮常见操作及任务给定初始区间为依据，形成可计算的保守区间；未经统一实验测定。", "grade_thresholds": "按默认值分级。油：低≤5g，中>5–15g，偏高>15–25g，高>25g；盐当量：低≤1g，中>1–2g，偏高>2–3g，高>3g；添加糖：低≤2g，中>2–5g，偏高>5–10g，高>10g。阈值均为项目内部规则。", "servings_estimate": 2, "standard_portion_g": 300, "authority_reference": "《中国居民膳食指南（2022）》：成人每日食盐不超过5g、烹调油25–30g、添加糖不超过50g且最好低于25g；《健康中国行动（2019—2030年）》倡导添加糖不高于25g；《餐饮食品营养标识指南》规定1mg钠相当于2.5mg食盐；《营养健康食堂建设指南》建议少用炸、煎、熏、烤并尽量减少油盐糖。上述均为每日总量或原则，不是单道菜测定值。", "calculation_priority": "已知配方/称量值优先；其次用营养标签或餐厅标示；均缺失时才使用本规则。含钠调味品按标签钠量折算：食盐当量(g)=钠(mg)×2.5/1000。", "project_estimate_flag": true, "standard_portion_definition": "成品可食部分300g/份；含随菜食用的汤汁或芡汁，不含骨、壳及弃去的炸油"}, "title": "烹饪方式油盐糖估算规则", "language": "zh-CN", "dataset_id": "cooking-rules-zh-cn-v1", "rule_count": 16, "updated_on": "2026-10-18", "intended_use": "供膳食搭配智能体在缺少完整配方/称量值时，按菜品主要烹饪方式估算额外带入成品的烹调油、食盐当量与添加糖。", "portion_basis": "各区间按一份300g成品可食部分计，约2名成人分食；按实际食用重量线性折算到个人。", "schema_version": "1.0.0"}	1
CR006	清炖/焖（非红烧）	{清炖,焖,煨,烩}	0	6	3	低	0.8	2	1.4	中	0	3	1.5	低	少油加水或高汤长时间加热，成品带少量汤汁但无明显糖色或浓油酱汁。	不炒糖色、不大量煸香底油；汤汁随菜食用。	先煸炒或收浓汁取上限；完全清炖取下限；出现糖色和浓酱油转用红烧。 在成品150–600g且配方浓度相近时，可按实际成品可食重量/300线性缩放；超出该范围应改用实际配方。	{"meta": {"limitations": "仅估算烹调额外带入成品的油、食盐当量和添加糖，不含原料天然脂肪、天然糖及天然钠；不代表人体实际吸收量。厨师手法、食材吸油性、裹粉、锅具、火候、沥油、汤汁摄入和调味品牌可使结果明显偏离。儿童、孕妇、老年人及慢病人群需另行设定个体化目标。", "source_urls": ["https://en.chinacdc.cn/health_topics/nutrition_health/202206/t20220616_259702.html", "https://www.nhc.gov.cn/guihuaxxs/c100133/201907/2a6ed52f1c264203b5351bdbbadd2da8.shtml", "https://www.nhc.gov.cn/wjw/c100175/202012/681df34f0e8f485fb33e8a659e30f6da.shtml", "https://www.nhc.gov.cn/sps/c100087/202404/90c64c79708740a1bca0ee31e524caf7.shtml"], "rule_version": "1.0.0 (2026-10-17)", "project_basis": "项目估计：以权威每日总量边界、烹饪方式的相对用油/调味强度、家庭与餐饮常见操作及任务给定初始区间为依据，形成可计算的保守区间；未经统一实验测定。", "grade_thresholds": "按默认值分级。油：低≤5g，中>5–15g，偏高>15–25g，高>25g；盐当量：低≤1g，中>1–2g，偏高>2–3g，高>3g；添加糖：低≤2g，中>2–5g，偏高>5–10g，高>10g。阈值均为项目内部规则。", "servings_estimate": 2, "standard_portion_g": 300, "authority_reference": "《中国居民膳食指南（2022）》：成人每日食盐不超过5g、烹调油25–30g、添加糖不超过50g且最好低于25g；《健康中国行动（2019—2030年）》倡导添加糖不高于25g；《餐饮食品营养标识指南》规定1mg钠相当于2.5mg食盐；《营养健康食堂建设指南》建议少用炸、煎、熏、烤并尽量减少油盐糖。上述均为每日总量或原则，不是单道菜测定值。", "calculation_priority": "已知配方/称量值优先；其次用营养标签或餐厅标示；均缺失时才使用本规则。含钠调味品按标签钠量折算：食盐当量(g)=钠(mg)×2.5/1000。", "project_estimate_flag": true, "standard_portion_definition": "成品可食部分300g/份；含随菜食用的汤汁或芡汁，不含骨、壳及弃去的炸油"}, "title": "烹饪方式油盐糖估算规则", "language": "zh-CN", "dataset_id": "cooking-rules-zh-cn-v1", "rule_count": 16, "updated_on": "2026-10-18", "intended_use": "供膳食搭配智能体在缺少完整配方/称量值时，按菜品主要烹饪方式估算额外带入成品的烹调油、食盐当量与添加糖。", "portion_basis": "各区间按一份300g成品可食部分计，约2名成人分食；按实际食用重量线性折算到个人。", "schema_version": "1.0.0"}	1
CR007	凉拌	{拌,冷拌,沙拉（中式调味）}	0	5	2.5	低	0.5	2	1.3	中	0	4	2	低	熟制或可生食原料与调味汁拌匀，不含高脂蛋黄酱型沙拉。	酱油、醋、香油、糖等全部随菜食用；食盐按含钠调味品折算。	不放油取下限；红油、芝麻酱、蛋黄酱或大量沙拉汁必须按配方计量，可能显著高于本区间。 在成品150–600g且配方浓度相近时，可按实际成品可食重量/300线性缩放；超出该范围应改用实际配方。	{"meta": {"limitations": "仅估算烹调额外带入成品的油、食盐当量和添加糖，不含原料天然脂肪、天然糖及天然钠；不代表人体实际吸收量。厨师手法、食材吸油性、裹粉、锅具、火候、沥油、汤汁摄入和调味品牌可使结果明显偏离。儿童、孕妇、老年人及慢病人群需另行设定个体化目标。", "source_urls": ["https://en.chinacdc.cn/health_topics/nutrition_health/202206/t20220616_259702.html", "https://www.nhc.gov.cn/guihuaxxs/c100133/201907/2a6ed52f1c264203b5351bdbbadd2da8.shtml", "https://www.nhc.gov.cn/wjw/c100175/202012/681df34f0e8f485fb33e8a659e30f6da.shtml", "https://www.nhc.gov.cn/sps/c100087/202404/90c64c79708740a1bca0ee31e524caf7.shtml"], "rule_version": "1.0.0 (2026-10-17)", "project_basis": "项目估计：以权威每日总量边界、烹饪方式的相对用油/调味强度、家庭与餐饮常见操作及任务给定初始区间为依据，形成可计算的保守区间；未经统一实验测定。", "grade_thresholds": "按默认值分级。油：低≤5g，中>5–15g，偏高>15–25g，高>25g；盐当量：低≤1g，中>1–2g，偏高>2–3g，高>3g；添加糖：低≤2g，中>2–5g，偏高>5–10g，高>10g。阈值均为项目内部规则。", "servings_estimate": 2, "standard_portion_g": 300, "authority_reference": "《中国居民膳食指南（2022）》：成人每日食盐不超过5g、烹调油25–30g、添加糖不超过50g且最好低于25g；《健康中国行动（2019—2030年）》倡导添加糖不高于25g；《餐饮食品营养标识指南》规定1mg钠相当于2.5mg食盐；《营养健康食堂建设指南》建议少用炸、煎、熏、烤并尽量减少油盐糖。上述均为每日总量或原则，不是单道菜测定值。", "calculation_priority": "已知配方/称量值优先；其次用营养标签或餐厅标示；均缺失时才使用本规则。含钠调味品按标签钠量折算：食盐当量(g)=钠(mg)×2.5/1000。", "project_estimate_flag": true, "standard_portion_definition": "成品可食部分300g/份；含随菜食用的汤汁或芡汁，不含骨、壳及弃去的炸油"}, "title": "烹饪方式油盐糖估算规则", "language": "zh-CN", "dataset_id": "cooking-rules-zh-cn-v1", "rule_count": 16, "updated_on": "2026-10-18", "intended_use": "供膳食搭配智能体在缺少完整配方/称量值时，按菜品主要烹饪方式估算额外带入成品的烹调油、食盐当量与添加糖。", "portion_basis": "各区间按一份300g成品可食部分计，约2名成人分食；按实际食用重量线性折算到个人。", "schema_version": "1.0.0"}	1
CR008	烤/空气炸	{烤箱烤,炙烤,空气炸,无油烤}	0	8	4	低	0.5	1.8	1.2	中	0	3	1.5	低	烤箱、烤架或空气炸锅加热，表面刷油或喷油较少。	不含大量烧烤酱、黄油或糖浆；原料自身析出的脂肪不算新增油。	无油空气炸取下限；多次刷油或刷酱取上限；蜜汁烤按糖醋/蜜汁规则。 在成品150–600g且配方浓度相近时，可按实际成品可食重量/300线性缩放；超出该范围应改用实际配方。	{"meta": {"limitations": "仅估算烹调额外带入成品的油、食盐当量和添加糖，不含原料天然脂肪、天然糖及天然钠；不代表人体实际吸收量。厨师手法、食材吸油性、裹粉、锅具、火候、沥油、汤汁摄入和调味品牌可使结果明显偏离。儿童、孕妇、老年人及慢病人群需另行设定个体化目标。", "source_urls": ["https://en.chinacdc.cn/health_topics/nutrition_health/202206/t20220616_259702.html", "https://www.nhc.gov.cn/guihuaxxs/c100133/201907/2a6ed52f1c264203b5351bdbbadd2da8.shtml", "https://www.nhc.gov.cn/wjw/c100175/202012/681df34f0e8f485fb33e8a659e30f6da.shtml", "https://www.nhc.gov.cn/sps/c100087/202404/90c64c79708740a1bca0ee31e524caf7.shtml"], "rule_version": "1.0.0 (2026-10-17)", "project_basis": "项目估计：以权威每日总量边界、烹饪方式的相对用油/调味强度、家庭与餐饮常见操作及任务给定初始区间为依据，形成可计算的保守区间；未经统一实验测定。", "grade_thresholds": "按默认值分级。油：低≤5g，中>5–15g，偏高>15–25g，高>25g；盐当量：低≤1g，中>1–2g，偏高>2–3g，高>3g；添加糖：低≤2g，中>2–5g，偏高>5–10g，高>10g。阈值均为项目内部规则。", "servings_estimate": 2, "standard_portion_g": 300, "authority_reference": "《中国居民膳食指南（2022）》：成人每日食盐不超过5g、烹调油25–30g、添加糖不超过50g且最好低于25g；《健康中国行动（2019—2030年）》倡导添加糖不高于25g；《餐饮食品营养标识指南》规定1mg钠相当于2.5mg食盐；《营养健康食堂建设指南》建议少用炸、煎、熏、烤并尽量减少油盐糖。上述均为每日总量或原则，不是单道菜测定值。", "calculation_priority": "已知配方/称量值优先；其次用营养标签或餐厅标示；均缺失时才使用本规则。含钠调味品按标签钠量折算：食盐当量(g)=钠(mg)×2.5/1000。", "project_estimate_flag": true, "standard_portion_definition": "成品可食部分300g/份；含随菜食用的汤汁或芡汁，不含骨、壳及弃去的炸油"}, "title": "烹饪方式油盐糖估算规则", "language": "zh-CN", "dataset_id": "cooking-rules-zh-cn-v1", "rule_count": 16, "updated_on": "2026-10-18", "intended_use": "供膳食搭配智能体在缺少完整配方/称量值时，按菜品主要烹饪方式估算额外带入成品的烹调油、食盐当量与添加糖。", "portion_basis": "各区间按一份300g成品可食部分计，约2名成人分食；按实际食用重量线性折算到个人。", "schema_version": "1.0.0"}	1
CR009	快炒	{炒,小炒,清炒}	10	20	15	中	1	2	1.5	中	0	4	2	低	家庭或食堂常见少量底油、短时翻炒，成品无大量明油。	大部分加入的油随菜进入成品；不包含食材原有脂肪。	不粘锅、喷油或明确少油取下限；餐饮大火、表面有明油取上限。 在成品150–600g且配方浓度相近时，可按实际成品可食重量/300线性缩放；超出该范围应改用实际配方。	{"meta": {"limitations": "仅估算烹调额外带入成品的油、食盐当量和添加糖，不含原料天然脂肪、天然糖及天然钠；不代表人体实际吸收量。厨师手法、食材吸油性、裹粉、锅具、火候、沥油、汤汁摄入和调味品牌可使结果明显偏离。儿童、孕妇、老年人及慢病人群需另行设定个体化目标。", "source_urls": ["https://en.chinacdc.cn/health_topics/nutrition_health/202206/t20220616_259702.html", "https://www.nhc.gov.cn/guihuaxxs/c100133/201907/2a6ed52f1c264203b5351bdbbadd2da8.shtml", "https://www.nhc.gov.cn/wjw/c100175/202012/681df34f0e8f485fb33e8a659e30f6da.shtml", "https://www.nhc.gov.cn/sps/c100087/202404/90c64c79708740a1bca0ee31e524caf7.shtml"], "rule_version": "1.0.0 (2026-10-17)", "project_basis": "项目估计：以权威每日总量边界、烹饪方式的相对用油/调味强度、家庭与餐饮常见操作及任务给定初始区间为依据，形成可计算的保守区间；未经统一实验测定。", "grade_thresholds": "按默认值分级。油：低≤5g，中>5–15g，偏高>15–25g，高>25g；盐当量：低≤1g，中>1–2g，偏高>2–3g，高>3g；添加糖：低≤2g，中>2–5g，偏高>5–10g，高>10g。阈值均为项目内部规则。", "servings_estimate": 2, "standard_portion_g": 300, "authority_reference": "《中国居民膳食指南（2022）》：成人每日食盐不超过5g、烹调油25–30g、添加糖不超过50g且最好低于25g；《健康中国行动（2019—2030年）》倡导添加糖不高于25g；《餐饮食品营养标识指南》规定1mg钠相当于2.5mg食盐；《营养健康食堂建设指南》建议少用炸、煎、熏、烤并尽量减少油盐糖。上述均为每日总量或原则，不是单道菜测定值。", "calculation_priority": "已知配方/称量值优先；其次用营养标签或餐厅标示；均缺失时才使用本规则。含钠调味品按标签钠量折算：食盐当量(g)=钠(mg)×2.5/1000。", "project_estimate_flag": true, "standard_portion_definition": "成品可食部分300g/份；含随菜食用的汤汁或芡汁，不含骨、壳及弃去的炸油"}, "title": "烹饪方式油盐糖估算规则", "language": "zh-CN", "dataset_id": "cooking-rules-zh-cn-v1", "rule_count": 16, "updated_on": "2026-10-18", "intended_use": "供膳食搭配智能体在缺少完整配方/称量值时，按菜品主要烹饪方式估算额外带入成品的烹调油、食盐当量与添加糖。", "portion_basis": "各区间按一份300g成品可食部分计，约2名成人分食；按实际食用重量线性折算到个人。", "schema_version": "1.0.0"}	1
CR010	滑炒/爆炒	{滑炒,爆炒,过油后炒}	15	25	20	偏高	1.2	2.5	1.9	中	0	5	2.5	中	需较多底油、滑油或高温爆香的炒制菜，汁水较少。	若先过油，按沥油后随成品带入的新增油估计，不是锅中总投油量。	充分沥油且少油复炒取下限；挂浆、吸油食材或明显明油取上限；过油程度很高可按油炸。 在成品150–600g且配方浓度相近时，可按实际成品可食重量/300线性缩放；超出该范围应改用实际配方。	{"meta": {"limitations": "仅估算烹调额外带入成品的油、食盐当量和添加糖，不含原料天然脂肪、天然糖及天然钠；不代表人体实际吸收量。厨师手法、食材吸油性、裹粉、锅具、火候、沥油、汤汁摄入和调味品牌可使结果明显偏离。儿童、孕妇、老年人及慢病人群需另行设定个体化目标。", "source_urls": ["https://en.chinacdc.cn/health_topics/nutrition_health/202206/t20220616_259702.html", "https://www.nhc.gov.cn/guihuaxxs/c100133/201907/2a6ed52f1c264203b5351bdbbadd2da8.shtml", "https://www.nhc.gov.cn/wjw/c100175/202012/681df34f0e8f485fb33e8a659e30f6da.shtml", "https://www.nhc.gov.cn/sps/c100087/202404/90c64c79708740a1bca0ee31e524caf7.shtml"], "rule_version": "1.0.0 (2026-10-17)", "project_basis": "项目估计：以权威每日总量边界、烹饪方式的相对用油/调味强度、家庭与餐饮常见操作及任务给定初始区间为依据，形成可计算的保守区间；未经统一实验测定。", "grade_thresholds": "按默认值分级。油：低≤5g，中>5–15g，偏高>15–25g，高>25g；盐当量：低≤1g，中>1–2g，偏高>2–3g，高>3g；添加糖：低≤2g，中>2–5g，偏高>5–10g，高>10g。阈值均为项目内部规则。", "servings_estimate": 2, "standard_portion_g": 300, "authority_reference": "《中国居民膳食指南（2022）》：成人每日食盐不超过5g、烹调油25–30g、添加糖不超过50g且最好低于25g；《健康中国行动（2019—2030年）》倡导添加糖不高于25g；《餐饮食品营养标识指南》规定1mg钠相当于2.5mg食盐；《营养健康食堂建设指南》建议少用炸、煎、熏、烤并尽量减少油盐糖。上述均为每日总量或原则，不是单道菜测定值。", "calculation_priority": "已知配方/称量值优先；其次用营养标签或餐厅标示；均缺失时才使用本规则。含钠调味品按标签钠量折算：食盐当量(g)=钠(mg)×2.5/1000。", "project_estimate_flag": true, "standard_portion_definition": "成品可食部分300g/份；含随菜食用的汤汁或芡汁，不含骨、壳及弃去的炸油"}, "title": "烹饪方式油盐糖估算规则", "language": "zh-CN", "dataset_id": "cooking-rules-zh-cn-v1", "rule_count": 16, "updated_on": "2026-10-18", "intended_use": "供膳食搭配智能体在缺少完整配方/称量值时，按菜品主要烹饪方式估算额外带入成品的烹调油、食盐当量与添加糖。", "portion_basis": "各区间按一份300g成品可食部分计，约2名成人分食；按实际食用重量线性折算到个人。", "schema_version": "1.0.0"}	1
