4	dietary-rules-zh-cn-v1	1.2.0	{"scope": {"food_allergies": ["peanut_allergy", "milk_allergy", "egg_allergy", "crustacean_shellfish_allergy", "tree_nut_allergy", "wheat_allergy", "fish_allergy", "soy_allergy", "sesame_allergy", "mollusk_allergy"], "chronic_conditions": ["diabetes", "hypertension", "hyperlipidemia", "gout", "obesity_weight_management"]}, "language": "zh-CN", "title_zh": "疾病与食物过敏膳食规则", "references": [{"url": "https://www.nhc.gov.cn/sps/c100088/202402/9ba512ba8e314a47a181db11d2fa188d.shtml", "title": "成人高尿酸血症与痛风食养指南（2024年版）", "used_for": ["痛风和高尿酸血症膳食原则", "嘌呤分级", "数据缺失时保守复核"], "organization": "国家卫生健康委员会", "reference_id": "NHC_GOUT_2024"}, {"url": "https://www.niddk.nih.gov/health-information/diabetes/overview/healthy-living-with-diabetes", "title": "Healthy Living with Diabetes", "used_for": ["糖尿病碳水管理", "减少添加糖", "优先富含纤维的食物"], "organization": "National Institute of Diabetes and Digestive and Kidney Diseases", "reference_id": "NIDDK_DIABETES"}, {"url": "https://www.nhlbi.nih.gov/health/dash-eating-plan", "title": "DASH Eating Plan", "used_for": ["高血压钠摄入管理", "DASH 优选模式"], "organization": "National Heart, Lung, and Blood Institute", "reference_id": "NHLBI_DASH"}, {"url": "https://www.nhlbi.nih.gov/health/blood-cholesterol/treatment", "title": "Blood Cholesterol Treatment", "used_for": ["限制饱和脂肪", "心脏健康饮食模式"], "organization": "National Heart, Lung, and Blood Institute", "reference_id": "NHLBI_CHOLESTEROL"}, {"url": "https://www.cdc.gov/healthy-weight-growth/healthy-eating/", "title": "Tips for Healthy Eating for a Healthy Weight", "used_for": ["体重管理", "营养密度较高的健康饮食模式"], "organization": "Centers for Disease Control and Prevention", "reference_id": "CDC_HEALTHY_WEIGHT"}, {"url": "https://www.niddk.nih.gov/health-information/diabetes/overview/preventing-type-2-diabetes/game-plan", "title": "Your Game Plan to Prevent Type 2 Diabetes", "used_for": ["控制高能量、高脂肪和高糖食物份量"], "organization": "National Institute of Diabetes and Digestive and Kidney Diseases", "reference_id": "NIDDK_WEIGHT"}, {"url": "https://www.fda.gov/consumers/consumer-updates/have-food-allergies-read-label", "title": "Have Food Allergies? Read the Label", "used_for": ["九大主要过敏原", "包装标签核查", "交叉接触提示"], "organization": "U.S. Food and Drug Administration", "reference_id": "FDA_ALLERGENS"}, {"url": "https://www.niaid.nih.gov/sites/default/files/faguidelinesexecsummary.pdf", "title": "Guidelines for the Diagnosis and Management of Food Allergy", "used_for": ["确诊食物过敏原的严格回避"], "organization": "National Institute of Allergy and Infectious Diseases", "reference_id": "NIAID_ALLERGY"}], "ruleset_id": "dietary-rules-zh-cn-v1", "updated_on": "2026-10-19", "action_levels": {"limit": {"rank": 60, "meaning_zh": "可摄入，但需要结合份量、单餐或全天目标限制。"}, "prefer": {"rank": 30, "meaning_zh": "同类食物中优先选择，不等于可以不限量食用。"}, "not_evaluable": {"rank": 10, "meaning_zh": "缺少计算所需字段，不能自动得出结论。"}, "strict_exclude": {"rank": 100, "meaning_zh": "严格排除，不进入推荐结果。"}, "review_required": {"rank": 20, "meaning_zh": "现有信息不足，需要查看配料、营养标签或人工核查。"}, "exclude_until_verified": {"rank": 90, "meaning_zh": "成分或交叉接触情况不明确，确认安全前不推荐。"}}, "data_contract": {"id_field": "food_id", "name_fields": ["name", "aliases"], "state_field": "state", "user_profile": {"activation_rule": "仅当 condition_id 对应条件 status=confirmed 时启用。", "conditions_path": "user_profile.conditions"}, "food_table_csv": "中式食材成分表/食物成分表.csv", "matching_rules": {"tag_match": "对 tags 按分号拆分后做完整标签精确匹配。", "dish_match": "任一已确认配料命中过敏规则，整道菜继承严格排除。", "allergen_match": "对 allergens 按分号拆分后做完整标签精确匹配，禁止用名称子串代替过敏原标签。", "selector_semantics": "同一 selector 中多个 *_any 条件按 OR；同一列表任一值命中即成立。", "allergen_status_gate": "只有已确认含 可按 allergens 自动命中；未核查 或空状态必须进入 exclude_until_verified，不得当作无过敏原。"}, "food_table_json": "中式食材成分表/食物成分表.json", "exact_token_fields": {"tags": {"delimiter": ";"}, "allergens": {"delimiter": ";"}}, "missing_value_policy": {"food_allergy": "allergen_status=未核查、状态缺失、配料不完整或交叉接触不明时返回 exclude_until_verified。", "chronic_condition": "逐配料检查所需营养字段；存在空值时输出已知小计、缺失食材和完整度，并返回 not_evaluable 或 review_required；不得把空值当0。", "chronic_condition_threshold_short_circuit": "若已知小计已达到或超过限制，可返回 limit 并同时标记 incomplete；否则不得据已知小计判定低于目标。"}, "allergen_status_field": "allergen_status", "allergen_status_values": {"未核查": "尚未完成过敏原核查；allergens 为空不得解释为安全。", "已确认含": "allergens 至少包含一个已核实的标准标签。", "确认不含": "已核查且不含当前规则覆盖的过敏原。"}, "available_nutrient_fields": ["energy_kcal", "protein_g", "fat_g", "carbohydrate_g", "fiber_g", "potassium_mg", "calcium_mg", "magnesium_mg", "sodium_mg", "cholesterol_mg", "sfa_g"], "unavailable_or_incomplete_fields": ["trans_fat_g", "added_sugar_g", "purine_mg"], "partially_populated_nutrient_fields": {"sfa_g": {"note_zh": "字段存在但覆盖不完整；不得用总脂肪替代饱和脂肪。", "total_rows": 128, "missing_rows": 82, "non_null_rows": 46}, "sodium_mg": {"note_zh": "椰子油原始中国食物成分查询页的钠项目为空，未跨来源推定为0。橄榄油钠已按 USDA 约 2mg/100g 补入。", "total_rows": 128, "non_null_rows": 127, "missing_food_ids": ["CN-1506"]}}}, "safety_policy": {"statements": ["本规则用于食材筛查和膳食提示，不用于诊断、处方或替代医生及注册营养师意见。", "过敏按严格排除处理；慢性疾病按限制、优选或提示处理，不把某一种普通食材默认设为绝对禁食。", "慢病目标值应优先读取用户经医生或营养师确认的个体方案。", "数据不足时返回不可判断或需要复核，不把缺失值当作 0。"], "emergency_message_zh": "如已出现呼吸困难、喉头紧缩、晕厥等严重过敏反应表现，应立即联系当地急救服务。"}, "schema_version": "1.2.0", "dish_evaluation": {"conflict_resolution": "同一食物命中多个动作时，采用 action_levels.rank 最高的动作。", "packaged_food_labels": {"contains_statement_action": "strict_exclude", "unknown_ingredient_action": "exclude_until_verified", "may_contain_statement_action": "exclude_until_verified"}, "ingredient_propagation": {"limit": "按实际食用克数汇总相关营养素，再与个体目标比较。", "strict_exclude": "任一配料为 strict_exclude 时，整道菜为 strict_exclude。", "exclude_until_verified": "任一配料为 exclude_until_verified 且无法核实时，整道菜为 exclude_until_verified。"}}, "food_allergy_rules": {"rules": [{"action": "strict_exclude", "rule_id": "allergy_peanut", "source_refs": ["FDA_ALLERGENS", "NIAID_ALLERGY"], "condition_id": "peanut_allergy", "condition_name_zh": "花生过敏", "allergens_tokens_any": ["花生"]}, {"action": "strict_exclude", "note_zh": "牛奶过敏不同于乳糖不耐受，本规则不用于乳糖不耐受。", "rule_id": "allergy_milk", "source_refs": ["FDA_ALLERGENS", "NIAID_ALLERGY"], "condition_id": "milk_allergy", "condition_name_zh": "牛奶过敏", "allergens_tokens_any": ["牛奶"]}, {"action": "strict_exclude", "rule_id": "allergy_egg", "source_refs": ["FDA_ALLERGENS", "NIAID_ALLERGY"], "condition_id": "egg_allergy", "uncertain_action": "exclude_until_verified", "condition_name_zh": "鸡蛋过敏", "uncertain_note_zh": "仅当标准 token“鸡蛋”出现在不确定性字段时触发；“可能含”“配方需复核”等状态描述不进入 token。", "allergens_tokens_any": ["鸡蛋"], "uncertain_tokens_any": ["鸡蛋"], "uncertain_token_source_fields": ["package_may_contain"]}, {"action": "strict_exclude", "rule_id": "allergy_crustacean_shellfish", "examples_zh": ["虾", "蟹", "龙虾"], "source_refs": ["FDA_ALLERGENS", "NIAID_ALLERGY"], "condition_id": "crustacean_shellfish_allergy", "condition_name_zh": "甲壳类水产过敏", "allergens_tokens_any": ["甲壳类水产"]}, {"action": "strict_exclude", "rule_id": "allergy_tree_nut", "source_refs": ["FDA_ALLERGENS", "NIAID_ALLERGY"], "condition_id": "tree_nut_allergy", "condition_name_zh": "树坚果过敏", "allergens_tokens_any": ["树坚果"]}, {"action": "strict_exclude", "note_zh": "小麦过敏不等同于乳糜泻或其他麸质相关疾病。", "rule_id": "allergy_wheat", "source_refs": ["FDA_ALLERGENS", "NIAID_ALLERGY"], "condition_id": "wheat_allergy", "condition_name_zh": "小麦过敏", "allergens_tokens_any": ["小麦"]}, {"action": "strict_exclude", "rule_id": "allergy_fish", "source_refs": ["FDA_ALLERGENS", "NIAID_ALLERGY"], "condition_id": "fish_allergy", "condition_name_zh": "鱼类过敏", "allergens_tokens_any": ["鱼类"]}, {"action": "strict_exclude", "rule_id": "allergy_soy", "source_refs": ["FDA_ALLERGENS", "NIAID_ALLERGY"], "condition_id": "soy_allergy", "condition_name_zh": "大豆过敏", "allergens_tokens_any": ["大豆"]}, {"action": "strict_exclude", "rule_id": "allergy_sesame", "source_refs": ["FDA_ALLERGENS", "NIAID_ALLERGY"], "condition_id": "sesame_allergy", "condition_name_zh": "芝麻过敏", "allergens_tokens_any": ["芝麻"]}, {"action": "strict_exclude", "note_zh": "软体贝类不是 FDA 九大过敏原中的甲壳类，但仍可单独引发过敏，因此作为独立规则处理。", "rule_id": "allergy_mollusk", "examples_zh": ["扇贝", "鱿鱼"], "source_refs": ["NIAID_ALLERGY"], "condition_id": "mollusk_allergy", "condition_name_zh": "软体贝类过敏", "allergens_tokens_any": ["软体贝类"]}], "rule_behavior": {"package_contains": "strict_exclude", "confirmed_allergen": "strict_exclude", "package_may_contain": "exclude_until_verified", "highly_refined_oil_note_zh": "现有食材库没有记录油脂精炼程度，不能仅凭名称自动放行；只有商品标签明确且个人医疗方案允许时才进入人工复核。", "unknown_recipe_or_cross_contact": "exclude_until_verified", "allergen_derived_oil_with_unknown_refining": "strict_exclude", "highly_refined_oil_with_explicit_label_and_clinical_plan": "review_required"}}, "chronic_condition_rules": [{"rules": [{"action": "limit", "rule_id": "diabetes_meal_carbohydrate_total", "evaluator": {"type": "portion_weighted_nutrient_sum", "formula": "sum(carbohydrate_g * grams / 100)", "target_path": "user_profile.diabetes.carbohydrate_target_g_per_meal", "nutrient_field": "carbohydrate_g", "when_target_missing": "review_required", "serving_amount_field": "grams"}, "message_zh": "碳水化合物并非完全禁止，应按个人单餐目标控制总量。"}, {"action": "limit", "rule_id": "diabetes_added_sugar_proxy", "selector": {"category_any": ["糖与甜味食材"]}, "message_zh": "限制添加糖和含糖食品，包装食品仍需查看营养标签与配料表。", "data_limitation": "食物成分表暂无 added_sugar_g；该规则只能识别明确归入糖与甜味食材的条目。"}, {"action": "prefer", "rule_id": "diabetes_prefer_fiber_rich_pattern", "selector": {"tags_any": ["全谷物"], "category_any": ["蔬菜", "豆类与豆制品", "水果与果汁"]}, "message_zh": "优先选择蔬菜、豆类、全谷物和完整水果，同时仍需计入碳水和份量。"}], "source_refs": ["NIDDK_DIABETES"], "condition_id": "diabetes", "default_mode": "advisory", "condition_name_zh": "糖尿病"}, {"rules": [{"action": "limit", "rule_id": "hypertension_sodium_total", "evaluator": {"type": "portion_weighted_nutrient_sum", "formula": "sum(sodium_mg * grams / 100)", "target_path": "user_profile.hypertension.sodium_target_mg_per_day", "nutrient_field": "sodium_mg", "missing_value_output": {"completeness_field": "sodium_data_completeness", "known_subtotal_field": "known_sodium_mg", "incomplete_flag_field": "sodium_total_incomplete", "missing_food_ids_field": "missing_sodium_food_ids"}, "serving_amount_field": "grams", "threshold_short_circuit": "已知小计达到或超过目标时可返回 limit + incomplete；否则保持 not_evaluable，不得判定达标。", "fallback_target_mg_per_day": 2000, "when_nutrient_field_missing": "not_evaluable"}, "message_zh": "食材天然钠与添加盐折算钠应合并计入全天目标。"}, {"action": "review_required", "rule_id": "hypertension_high_sodium_candidate_review", "selector": {"state_any": ["罐装（按条目说明）"], "category_any": ["调味料", "汤与酱料"]}, "message_zh": "调味品、汤酱和罐装食品的钠含量差异较大，应查看营养标签，不直接一律禁食。"}, {"action": "prefer", "rule_id": "hypertension_prefer_dash_pattern", "selector": {"tags_any": ["全谷物", "无额外加盐描述"], "category_any": ["蔬菜", "水果与果汁", "豆类与豆制品"]}, "message_zh": "优先选择蔬菜、水果、豆类、全谷物及明确无额外加盐的食物。"}], "source_refs": ["NHLBI_DASH"], "condition_id": "hypertension", "default_mode": "advisory", "condition_name_zh": "高血压", "reference_targets": {"note_zh": "仅作权威参考；实际目标应服从个人医疗方案。", "sodium_upper_mg_per_day": 2000, "salt_equivalent_upper_g_per_day": 5}}, {"rules": [{"action": "limit", "rule_id": "hyperlipidemia_saturated_fat_total", "evaluator": {"type": "portion_weighted_nutrient_sum", "formula": "sum(sfa_g * grams / 100)", "target_path": "user_profile.hyperlipidemia.saturated_fat_target_g_per_day", "nutrient_field": "sfa_g", "missing_value_output": {"completeness_field": "sfa_data_completeness", "known_subtotal_field": "known_sfa_g", "incomplete_flag_field": "sfa_total_incomplete", "missing_food_ids_field": "missing_sfa_food_ids"}, "serving_amount_field": "grams", "threshold_short_circuit": "已知小计达到或超过目标时可返回 limit + incomplete；否则保持 not_evaluable，不得判定达标。", "when_nutrient_field_missing": "not_evaluable"}, "message_zh": "饱和脂肪字段存在时立即计算；不得用总脂肪替代。"}, {"action": "review_required", "rule_id": "hyperlipidemia_trans_fat_review", "evaluator": {"type": "field_presence_required", "nutrient_field": "trans_fat_g", "when_nutrient_field_missing": "not_evaluable"}, "data_limitation": "当前食物表无反式脂肪字段，包装食品需查看营养标签和配料表。"}, {"action": "review_required", "rule_id": "hyperlipidemia_food_candidate_review", "selector": {"name_any": ["黄油", "淡奶油", "奶油奶酪", "全脂牛奶", "椰子油"], "category_any": ["烘焙食品"]}, "message_zh": "这些条目可能含较多饱和脂肪或配方差异，需要查看饱和脂肪、反式脂肪和配料信息。"}, {"action": "prefer", "rule_id": "hyperlipidemia_prefer_pattern", "selector": {"tags_any": ["全谷物", "瘦肉/去皮描述"], "category_any": ["蔬菜", "水果与果汁", "豆类与豆制品"]}, "message_zh": "优先选择富含纤维的植物性食物和明确标注的瘦肉或去皮禽肉。"}], "source_refs": ["NHLBI_CHOLESTEROL"], "condition_id": "hyperlipidemia", "default_mode": "advisory", "condition_name_zh": "高脂血症"}, {"rules": [{"action": "limit", "rule_id": "gout_high_purine_exclude_during_attack", "selector": {"purine_level_any": ["高", "较高"]}, "message_zh": "高或较高嘌呤食物应结合病情和专业方案限制；急性发作期按医疗建议执行。"}, {"action": "review_required", "rule_id": "gout_unknown_purine_review", "evaluator": {"type": "field_presence_required", "nutrient_field": "purine_level", "when_nutrient_field_missing": "review_required"}, "message_zh": "嘌呤等级缺失时不得默认安全，需要查证或人工复核。"}, {"action": "prefer", "rule_id": "gout_hydration_and_pattern", "message_zh": "在无心肾功能限制的前提下保证饮水，并保持均衡膳食；不以单一食物替代治疗。"}], "source_refs": ["NHC_GOUT_2024"], "condition_id": "gout", "default_mode": "advisory", "condition_name_zh": "痛风/高尿酸血症"}, {"rules": [{"action": "limit", "rule_id": "weight_management_daily_energy", "evaluator": {"type": "portion_weighted_nutrient_sum", "formula": "sum(energy_kcal * grams / 100)", "target_path": "user_profile.weight_management.energy_target_kcal_per_day", "nutrient_field": "energy_kcal", "when_target_missing": "review_required", "serving_amount_field": "grams"}, "message_zh": "按个人目标管理全天总能量，不设置适用于所有人的统一低热量阈值。"}, {"action": "limit", "rule_id": "weight_management_energy_dense_portion_review", "selector": {"category_any": ["糖与甜味食材", "油脂"]}, "message_zh": "控制添加糖和食用油脂的份量，不把任何单一食物作为减重的绝对禁忌。"}, {"action": "prefer", "rule_id": "weight_management_prefer_nutrient_dense_pattern", "selector": {"tags_any": ["全谷物"], "category_any": ["蔬菜", "水果与果汁", "豆类与豆制品"]}, "message_zh": "在个人能量目标内优先选择蔬菜、完整水果、豆类和全谷物。"}], "source_refs": ["C