calcium	{"id": "calcium", "name": "钙", "aliases": ["Ca"], "sources": ["牛奶、酸奶和奶酪", "强化植物饮品", "石膏或钙盐凝固豆腐", "带骨小鱼和罐装沙丁鱼", "羽衣甘蓝、小白菜等低草酸绿叶菜", "芝麻酱"], "category": "矿物质", "function": ["构成骨骼和牙齿的主要矿物质。", "参与肌肉收缩、神经传导、血管功能和血液凝固。", "作为细胞内信号参与多种酶和激素反应。"], "absorption": {"enhancers": ["维生素D促进肠道钙吸收。", "分次摄入通常比一次大量补充吸收更好。"], "inhibitors": ["菠菜等食物中的草酸和部分谷豆中的植酸会降低同餐钙吸收。", "年龄增长、维生素D不足和吸收不良可降低利用率。"], "at_risk_groups": ["乳制品和替代来源摄入不足者", "绝经后女性", "老年人", "乳糖不耐受但未合理替代者", "纯素且膳食安排不当者", "吸收不良者"]}, "deficiency": {"interpretation": "这些表现并非该营养素缺乏所特有，不能依据单个症状或症状组合自行判断缺乏；是否缺乏需结合膳食史、疾病与用药情况，并由专业人员在必要时进行检查和评估。", "possible_manifestations": ["长期摄入不足可能加速骨量流失并增加骨质疏松风险。", "明显低钙血症可能出现口周或肢端麻木、肌肉痉挛；严重时可有心律异常或惊厥。"]}, "references": [{"url": "https://ods.od.nih.gov/factsheets/Calcium-HealthProfessional/", "title": "Calcium—Health Professional Fact Sheet", "accessed": "2026-10-18", "organization": "美国国立卫生研究院膳食补充剂办公室（NIH ODS）"}], "interaction": ["维生素D促进钙吸收，维生素K和镁参与骨代谢。", "一次大量钙补充剂可能降低铁、锌和某些药物的吸收，应按医嘱错开。", "高钠饮食可增加尿钙排出。"]}	1	2026-10-22 00:55:26.389874+08
iron	{"id": "iron", "name": "铁", "aliases": ["Fe", "血红素铁", "非血红素铁"], "sources": ["红肉和动物肝脏", "贝类", "禽肉和鱼类", "豆类和豆腐", "深绿色叶菜", "坚果和种子", "强化谷物"], "category": "矿物质", "function": ["构成血红蛋白和肌红蛋白，参与氧运输和储存。", "作为多种酶的组成部分，参与能量代谢、免疫和神经发育。"], "absorption": {"enhancers": ["肉类中的血红素铁吸收率通常高于植物性非血红素铁。", "维生素C和肉、鱼、禽类可提高同餐非血红素铁吸收。"], "inhibitors": ["植酸、茶和咖啡中的多酚会降低同餐非血红素铁吸收。", "较大量钙可能短暂降低同餐铁吸收。", "胃酸不足、乳糜泻和胃肠手术可影响吸收。"], "at_risk_groups": ["月经量较大的女性", "孕妇", "婴幼儿和青春期人群", "频繁献血者", "胃肠道慢性失血者", "纯素或素食但搭配不当者", "吸收不良者"]}, "deficiency": {"interpretation": "这些表现并非该营养素缺乏所特有，不能依据单个症状或症状组合自行判断缺乏；是否缺乏需结合膳食史、疾病与用药情况，并由专业人员在必要时进行检查和评估。", "possible_manifestations": ["铁储备下降早期可能没有明显症状。", "缺铁性贫血可能出现乏力、虚弱、面色苍白、活动后气短、心悸或注意力下降。", "部分人可能出现异食癖、舌炎或不宁腿等表现。"]}, "references": [{"url": "https://ods.od.nih.gov/factsheets/Iron-HealthProfessional/", "title": "Iron—Health Professional Fact Sheet", "accessed": "2026-10-18", "organization": "美国国立卫生研究院膳食补充剂办公室（NIH ODS）"}], "interaction": ["维生素C可显著促进非血红素铁吸收。", "维生素A和铜参与铁动员、运输和利用。", "高剂量铁和锌补充剂同服可能相互竞争。", "铁过量同样有害，不应仅凭疲劳自行补铁。"]}	1	2026-10-22 00:55:26.389874+08
zinc	{"id": "zinc", "name": "锌", "aliases": ["Zn"], "sources": ["牡蛎和其他贝类", "红肉", "禽肉", "奶制品", "豆类", "坚果和种子", "全谷物"], "category": "矿物质", "function": ["是数百种酶和转录因子的组成或调节成分。", "参与DNA和蛋白质合成、细胞分裂、免疫、伤口愈合及生长发育。", "支持正常味觉和嗅觉。"], "absorption": {"enhancers": ["动物性食物中的锌通常生物利用率较高。", "浸泡、发芽和发酵可降低豆谷中的植酸，从而改善锌利用。"], "inhibitors": ["全谷物和豆类中的植酸会结合锌并降低吸收。", "吸收不良和长期腹泻会增加损失。"], "at_risk_groups": ["纯素或素食且膳食安排不当者", "孕妇和哺乳期人群", "炎症性肠病或吸收不良者", "酒精使用障碍者", "婴幼儿和生长快速的青少年"]}, "deficiency": {"interpretation": "这些表现并非该营养素缺乏所特有，不能依据单个症状或症状组合自行判断缺乏；是否缺乏需结合膳食史、疾病与用药情况，并由专业人员在必要时进行检查和评估。", "possible_manifestations": ["可能出现食欲下降、味觉或嗅觉减退、伤口愈合延迟和感染易感性增加。", "儿童长期缺乏可能影响生长和性成熟。", "较严重时可能出现脱发、皮炎或腹泻。"]}, "references": [{"url": "https://ods.od.nih.gov/factsheets/Zinc-HealthProfessional/", "title": "Zinc—Health Professional Fact Sheet", "accessed": "2026-10-18", "organization": "美国国立卫生研究院膳食补充剂办公室（NIH ODS）"}], "interaction": ["长期高剂量锌会诱发铜缺乏。", "高剂量铁补充剂与锌空腹同服时可能竞争吸收。", "锌参与维生素A转运和代谢。"]}	1	2026-10-22 00:55:26.389874+08
selenium	{"id": "selenium", "name": "硒", "aliases": ["Se"], "sources": ["海产品", "肉类和禽肉", "动物内脏", "鸡蛋", "谷物", "巴西坚果（含量高且波动大）"], "category": "矿物质", "function": ["构成谷胱甘肽过氧化物酶、硫氧还蛋白还原酶等硒蛋白。", "参与抗氧化防御、甲状腺激素代谢、DNA合成、生殖和免疫功能。"], "absorption": {"enhancers": ["多数膳食硒形式吸收率较高。"], "inhibitors": ["植物性食物硒含量受土壤硒水平影响很大，因此仅凭食物名称难以准确判断摄入量。"], "at_risk_groups": ["长期食用低硒地区本地产食物且饮食单一者", "长期肾透析者", "部分HIV感染者", "严重吸收不良者"]}, "deficiency": {"interpretation": "这些表现并非该营养素缺乏所特有，不能依据单个症状或症状组合自行判断缺乏；是否缺乏需结合膳食史、疾病与用药情况，并由专业人员在必要时进行检查和评估。", "possible_manifestations": ["单独硒缺乏通常不产生特异症状，但可增加其他应激因素下发生疾病的易感性。", "极低硒地区的严重缺乏与克山病相关。", "硒不足还可能加重碘缺乏对甲状腺功能的影响。"]}, "references": [{"url": "https://ods.od.nih.gov/factsheets/Selenium-HealthProfessional/", "title": "Selenium—Health Professional Fact Sheet", "accessed": "2026-10-18", "organization": "美国国立卫生研究院膳食补充剂办公室（NIH ODS）"}], "interaction": ["硒参与甲状腺激素的活化和失活，与碘营养密切相关。", "硒和维生素E均参与抗氧化保护，但不能互相完全替代。", "硒过量可导致脱发、指甲改变、蒜味口气和神经症状，不宜随意高剂量补充。"]}	1	2026-10-22 00:55:26.389874+08
iodine	{"id": "iodine", "name": "碘", "aliases": ["I"], "sources": ["碘盐", "海鱼和贝类", "海藻（含量差异极大）", "牛奶和乳制品", "鸡蛋"], "category": "矿物质", "function": ["是甲状腺激素T4和T3的组成成分。", "通过甲状腺激素调节能量代谢、生长发育。", "孕期和婴幼儿期对脑和神经系统发育尤其重要。"], "absorption": {"enhancers": ["碘盐是稳定、可控的膳食碘来源；按当地公共卫生建议使用。"], "inhibitors": ["严重碘不足时，大量摄入某些生的十字花科植物、木薯等致甲状腺肿物质可能加重影响，但正常多样化饮食通常无需回避。", "碘含量会因土壤、饲料和加工方式而变化。"], "at_risk_groups": ["不使用碘盐且海产品、奶蛋摄入少者", "孕妇和哺乳期人群", "严格纯素者", "居住在缺碘地区且食物来源单一者"]}, "deficiency": {"interpretation": "这些表现并非该营养素缺乏所特有，不能依据单个症状或症状组合自行判断缺乏；是否缺乏需结合膳食史、疾病与用药情况，并由专业人员在必要时进行检查和评估。", "possible_manifestations": ["可能导致甲状腺肿和甲状腺功能减退。", "孕期严重缺乏可能损害胎儿脑发育。", "儿童长期不足可能影响生长和认知发育。"]}, "references": [{"url": "https://ods.od.nih.gov/factsheets/Iodine-HealthProfessional/", "title": "Iodine—Health Professional Fact Sheet", "accessed": "2026-10-18", "organization": "美国国立卫生研究院膳食补充剂办公室（NIH ODS）"}], "interaction": ["硒依赖酶参与甲状腺激素转化，因此硒不足可能加重碘缺乏影响。", "铁缺乏可能影响甲状腺过氧化物酶功能。", "碘过量同样可能引起甲状腺功能异常，海藻和补充剂不宜无控制摄入。"]}	1	2026-10-22 00:55:26.389874+08
potassium	{"id": "potassium", "name": "钾", "aliases": ["K"], "sources": ["土豆和红薯", "豆类", "菠菜等绿叶菜", "番茄", "香蕉和柑橘", "牛奶和酸奶", "鱼肉和禽肉"], "category": "矿物质", "function": ["是主要细胞内阳离子，参与体液和酸碱平衡。", "维持神经冲动传导、肌肉收缩和正常心律。", "较高的膳食钾与较低钠摄入共同有助于血压管理。"], "absorption": {"enhancers": ["食物中的钾通常吸收良好。"], "inhibitors": ["持续呕吐、腹泻、利尿剂或泻药使用会增加钾丢失。", "镁缺乏可使低钾更难纠正。"], "at_risk_groups": ["长期腹泻或呕吐者", "使用排钾利尿剂者", "滥用泻药者", "某些肾上腺或肾小管疾病患者", "镁缺乏者"]}, "deficiency": {"interpretation": "这些表现并非该营养素缺乏所特有，不能依据单个症状或症状组合自行判断缺乏；是否缺乏需结合膳食史、疾病与用药情况，并由专业人员在必要时进行检查和评估。", "possible_manifestations": ["真正的低钾血症通常由呕吐、腹泻、药物或疾病导致，而不只是普通饮食不足。", "可能出现肌无力、乏力、便秘或肌肉痉挛。", "严重低钾可导致心律失常或瘫痪。"]}, "references": [{"url": "https://ods.od.nih.gov/factsheets/Potassium-HealthProfessional/", "title": "Potassium—Health Professional Fact Sheet", "accessed": "2026-10-18", "organization": "美国国立卫生研究院膳食补充剂办公室（NIH ODS）"}], "interaction": ["钾与钠共同影响体液平衡和血压。", "镁不足可加重钾丢失。", "肾功能不全或使用ACE抑制剂、ARB、保钾利尿剂者可能发生高钾，不能自行大量补钾或使用含钾盐替代品。"]}	1	2026-10-22 00:55:26.389874+08
magnesium	{"id": "magnesium", "name": "镁", "aliases": ["Mg"], "sources": ["南瓜子、芝麻和其他种子", "杏仁等坚果", "豆类", "全谷物", "菠菜等绿叶菜", "黑巧克力"], "category": "矿物质", "function": ["参与数百种酶反应，包括ATP利用、蛋白质和核酸合成。", "支持神经传导、肌肉收缩、心律、血糖调节和血压调节。", "参与骨结构和维生素D代谢。"], "absorption": {"enhancers": ["多样化摄入坚果、豆类、全谷和绿叶菜有助满足需要。"], "inhibitors": ["长期腹泻、脂肪泻和胃肠手术可减少吸收或增加损失。", "长期使用质子泵抑制剂或某些利尿剂可能降低镁状态。"], "at_risk_groups": ["胃肠疾病或吸收不良者", "2型糖尿病患者", "酒精使用障碍者", "老年人", "长期使用相关药物者"]}, "deficiency": {"interpretation": "这些表现并非该营养素缺乏所特有，不能依据单个症状或症状组合自行判断缺乏；是否缺乏需结合膳食史、疾病与用药情况，并由专业人员在必要时进行检查和评估。", "possible_manifestations": ["早期可能有食欲下降、恶心、乏力或虚弱。", "进一步缺乏可能出现麻木、肌肉抽搐或痉挛。", "严重时可出现心律异常、惊厥，并常伴低钾或低钙。"]}, "references": [{"url": "https://ods.od.nih.gov/factsheets/Magnesium-HealthProfessional/", "title": "Magnesium—Health Professional Fact Sheet", "accessed": "2026-10-18", "organization": "美国国立卫生研究院膳食补充剂办公室（NIH ODS）"}], "interaction": ["镁参与维生素D活化以及甲状旁腺激素和钙稳态。", "镁缺乏可使低钾和低钙难以纠正。", "镁补充剂可影响部分抗生素和双膦酸盐吸收，需要错开服用。"]}	1	2026-10-22 00:55:26.389874+08
phosphorus	{"id": "phosphorus", "name": "磷", "aliases": ["P", "磷酸盐"], "sources": ["奶和乳制品", "肉类和禽肉", "鱼类", "鸡蛋", "豆类", "坚果和种子", "全谷物", "含磷酸盐食品添加剂的加工食品"], "category": "矿物质", "function": ["与钙共同构成骨骼和牙齿。", "构成ATP、核酸和细胞膜磷脂。", "参与酸碱平衡、细胞信号和能量代谢。"], "absorption": {"enhancers": ["动物性食物和食品添加磷通常吸收率较高。", "维生素D可促进肠道磷吸收。"], "inhibitors": ["植物种子中的磷多以植酸形式存在，人体吸收率相对较低。", "长期大量使用含铝、钙或镁的某些抗酸剂可能结合磷。"], "at_risk_groups": ["严重营养不良后快速再喂养者", "长期大量饮酒者", "严重吸收不良者", "某些遗传性肾小管疾病患者"]}, "deficiency": {"interpretation": "这些表现并非该营养素缺乏所特有，不能依据单个症状或症状组合自行判断缺乏；是否缺乏需结合膳食史、疾病与用药情况，并由专业人员在必要时进行检查和评估。", "possible_manifestations": ["单纯膳食性缺乏少见。", "明显低磷血症可能出现肌无力、骨痛、食欲下降或意识改变。", "长期严重不足可导致佝偻病或骨软化。"]}, "references": [{"url": "https://ods.od.nih.gov/factsheets/Phosphorus-HealthProfessional/", "title": "Phosphorus—Health Professional Fact Sheet", "accessed": "2026-10-18", "organization": "美国国立卫生研究院膳食补充剂办公室（NIH ODS）"}], "interaction": ["钙、磷、维生素D和甲状旁腺激素共同调节骨与血液中的矿物质平衡。", "慢性肾病患者可能需要限制高吸收率的添加磷，应接受专业指导。"]}	1	2026-10-22 00:55:26.389874+08
copper	{"id": "copper", "name": "铜", "aliases": ["Cu"], "sources": ["贝类", "动物肝脏", "坚果和种子", "全谷物", "豆类", "可可和黑巧克力"], "category": "矿物质", "function": ["参与铁代谢和红细胞形成。", "参与结缔组织合成、神经系统功能、免疫和能量代谢。", "构成超氧化物歧化酶等抗氧化酶。"], "absorption": {"enhancers": ["普通混合膳食通常可提供并吸收铜。"], "inhibitors": ["长期高剂量锌会诱导肠道金属硫蛋白并阻碍铜吸收。", "胃肠手术和严重吸收不良可降低铜状态。"], "at_risk_groups": ["长期高剂量补锌者", "减重或胃切除手术后人群", "乳糜泻等吸收不良者", "罕见Menkes病患者"]}, "deficiency": {"interpretation": "这些表现并非该营养素缺乏所特有，不能依据单个症状或症状组合自行判断缺乏；是否缺乏需结合膳食史、疾病与用药情况，并由专业人员在必要时进行检查和评估。", "possible_manifestations": ["可能出现贫血和中性粒细胞减少。", "长期严重缺乏可导致骨骼异常、色素减退、感觉异常、步态不稳或脊髓神经病变。"]}, "references": [{"url": "https://ods.od.nih.gov/factsheets/Copper-HealthProfessional/", "title": "Copper—Health Professional Fact Sheet", "accessed": "2026-10-18", "organization": "美国国立卫生研究院膳食补充剂办公室（NIH ODS）"}], "interaction": ["锌过量是获得性铜缺乏的重要原因。", "铜参与铁的动员和转运，铜缺乏可表现为对普通补铁反应不佳的贫血。"]}	1	2026-10-22 00:55:26.389874+08
manganese	{"id": "manganese", "name": "锰", "aliases": ["Mn"], "sources": ["全谷物", "坚果", "豆类", "茶", "绿叶蔬菜", "部分贝类"], "category": "矿物质", "function": ["作为多种酶的辅因子，参与氨基酸、胆固醇、葡萄糖和碳水化合物代谢。", "参与骨形成、伤口愈合和抗氧化酶锰超氧化物歧化酶功能。"], "absorption": {"enhancers": ["胃肠道会根据体内状态调节锰吸收，整体吸收率较低。"], "inhibitors": ["较高的铁、钙或磷摄入可能降低锰吸收。", "铁缺乏时锰吸收可能增加。"], "at_risk_groups": ["长期极度单一饮食者", "长期完全肠外营养且配方缺失者", "罕见遗传性锰转运异常患者"]}, "deficiency": {"interpretation": "这些表现并非该营养素缺乏所特有，不能依据单个症状或症状组合自行判断缺乏；是否缺乏需结合膳食史、疾病与用药情况，并由专业人员在必要时进行检查和评估。", "possible_manifestations": ["人体锰缺乏非常少见，已报道表现不一致。", "在极少数实验或特殊情况下可能涉及骨形成、生长或代谢异常。"]}, "references": [{"url": "https://ods.od.nih.gov/factsheets/Manganese-HealthProfessional/", "title": "Manganese—Health Professional Fact Sheet", "accessed": "2026-10-18", "organization": "美国国立卫生研究院膳食补充剂办公室（NIH ODS）"}], "interaction": ["铁和锰共享部分转运途径，铁缺乏可能增加锰吸收。", "过量锰主要是职业或环境暴露问题，可产生神经毒性；不能因缺乏少见而自行使用高剂量补充剂。"]}	1	2026-10-22 00:55:26.389874+08
omega_3	{"id": "omega_3", "name": "ω-3脂肪酸", "aliases": ["Omega-3", "n-3脂肪酸", "ALA", "EPA", "DHA"], "sources": ["三文鱼、沙丁鱼、鲭鱼、鲱鱼等富脂鱼", "贝类和其他海产品", "藻油中的DHA和部分EPA", "亚麻籽和奇亚籽中的ALA", "核桃", "菜籽油和大豆油"], "category": "脂肪酸", "function": ["构成细胞膜磷脂，DHA在脑和视网膜中含量较高。", "提供能量，并作为多种脂质信号分子的前体。", "EPA和DHA参与心血管、免疫和炎症调节相关生理过程。"], "absorption": {"enhancers": ["作为膳食脂肪可在胆汁和胰酶参与下高效吸收。", "直接食用鱼类或藻油中的EPA、DHA能更有效提高体内水平。"], "inhibitors": ["ALA转化为EPA并进一步转化为DHA的比例有限，不能假定植物ALA可以完全替代EPA和DHA。", "脂肪吸收不良会降低吸收。"], "at_risk_groups": ["长期不食用鱼类海产品且缺少ALA来源者", "脂肪吸收不良者", "缺少必需脂肪酸的长期肠外营养患者", "饮食极度限制脂肪者"]}, "deficiency": {"interpretation": "这些表现并非该营养素缺乏所特有，不能依据单个症状或症状组合自行判断缺乏；是否缺乏需结合膳食史、疾病与用药情况，并由专业人员在必要时进行检查和评估。", "possible_manifestations": ["经典必需脂肪酸缺乏在健康人群中很少见。", "严重缺乏可能出现皮肤粗糙、鳞屑和皮炎。", "目前没有仅凭某个症状判断EPA或DHA不足的公认界值。"]}, "references": [{"url": "https://ods.od.nih.gov/factsheets/Omega3FattyAcids-HealthProfessional/", "title": "Omega-3 Fatty Acids—Health Professional Fact Sheet", "accessed": "2026-10-18", "organization": "美国国立卫生研究院膳食补充剂办公室（NIH ODS）"}], "interaction": ["ω-3和ω-6脂肪酸会共享部分去饱和与延长酶，但仅用两者比例评价膳食并不充分。", "维生素E可帮助保护多不饱和脂肪酸免受氧化。", "高剂量EPA或DHA补充剂可能与抗凝或抗血小板药物共同增加出血倾向，应由专业人员评估。"]}	1	2026-10-22 00:55:26.389874+08
dietary_fiber	{"id": "dietary_fiber", "name": "膳食纤维", "aliases": ["可溶性纤维", "不溶性纤维", "dietary fiber"], "sources": ["全谷物和麸皮", "豆类", "蔬菜", "完整水果", "坚果和种子"], "category": "其他", "function": ["增加粪便体积并促进规律排便。", "部分可溶性或可发酵纤维可被肠道微生物利用并产生短链脂肪酸。", "部分纤维可延缓营养物质吸收，有助于餐后血糖和血脂管理。", "提高饱腹感，是植物性食物整体健康作用的一部分。"], "absorption": {"enhancers": ["逐步增加摄入并同时保证适量饮水，有助于胃肠道适应。", "混合摄入全谷物、豆类、蔬果、坚果和种子，可获得不同类型纤维。"], "inhibitors": ["膳食纤维本身大多不在小肠消化吸收；这是其定义和生理作用的一部分。", "短时间内突然大量增加可能导致腹胀、排气或腹部不适。"], "at_risk_groups": ["精制谷物和高度加工食品比例高者", "蔬菜、水果、豆类和全谷物摄入少者", "食量较少的老年人", "因不恰当限制饮食而减少植物性食物者"]}, "deficiency": {"interpretation": "这些表现并非该营养素缺乏所特有，不能依据单个症状或症状组合自行判断缺乏；是否缺乏需结合膳食史、疾病与用药情况，并由专业人员在必要时进行检查和评估。", "possible_manifestations": ["膳食纤维没有与维生素缺乏相同意义上的单一缺乏病。", "长期摄入很少可能与粪便量减少、排便困难和整体膳食质量较低有关。", "便秘等表现有许多其他原因，不能据此反推一定是纤维不足。"]}, "references": [{"url": "https://www.accessdata.fda.gov/scripts/InteractiveNutritionFactsLabel/assets/InteractiveNFL_DietaryFiber_October2021.pdf", "title": "Interactive Nutrition Facts Label—Dietary Fiber", "accessed": "2026-10-18", "organization": "美国食品药品监督管理局（FDA）"}, {"url": "https://medlineplus.gov/dietaryfiber.html", "title": "Dietary Fiber", "accessed": "2026-10-18", "organization": "美国国家医学图书馆 MedlinePlus"}], "interaction": ["水分有助于纤维发挥正常排便作用。", "大量纤维补充剂可能影响部分药物吸收，应查看药品说明或咨询专业人员。", "极高纤维摄入可能降低铁、锌、钙和镁等矿物质的利用，但普通多样化膳食通常同时提供这些矿物质。"]}	1	2026-10-22 00:55:26.389874+08
sodium	{"id": "sodium", "name": "钠", "aliases": ["钠离子", "sodium"], "sources": ["食盐", "酱油及其他含钠调味品", "腌制和加工食品", "部分包装食品和餐饮食品"], "category": "矿物质", "function": ["维持细胞外液容量、渗透压和酸碱平衡。", "参与神经冲动传导和肌肉收缩。"], "absorption": {"enhancers": ["膳食钠主要在小肠吸收，通常吸收率较高。"], "inhibitors": ["持续呕吐、腹泻、大量出汗或某些利尿剂可增加钠丢失。"], "at_risk_groups": ["大量出汗且补液不当者", "持续呕吐或腹泻者", "使用影响水钠平衡药物者"]}, "deficiency": {"interpretation": "这些表现不特异，低钠血症也可能由疾病或水摄入异常引起，不能自行补盐诊断或治疗；疑似严重症状应及时就医。", "possible_manifestations": ["单纯膳食摄入不足较少见；大量出汗、呕吐、腹泻或某些药物情况下可能出现低钠血症。", "低钠血症可伴恶心、头痛、乏力、意识混乱，严重时可危及生命。"]}, "references": [{"url": "https://www.who.int/news-room/fact-sheets/detail/salt-reduction", "title": "Salt reduction", "accessed": "2026-10-19", "organization": "世界卫生组织（WHO）"}, {"url": "https://www.nhc.gov.cn/sps/c100088/202301/f01895a06c5349ef999f25da833c166d.shtml", "title": "成人高血压食养指南（2023年版）", "accessed": "2026-10-19", "organization": "国家卫生健康委员会"}], "interaction": ["长期钠摄入过多与血压升高相关；高血压人群应把天然钠和添加盐合并计算。", "钾摄入与钠钾平衡相关，但肾病患者不应自行大量补钾。"]}	1	2026-10-22 00:55:26.389874+08
